  ok(false, 'ngoại lệ: ' + e.message + '\n' + log.slice(-1500));
}
stop();
await sleep(500);
console.log(fails ? `${fails} LỖI` : 'TẤT CẢ ĐẠT');
process.exit(fails ? 1 : 0);
